import json
from pathlib import Path
cfg=json.loads(Path('v3-app/verification/set15/config.json').read_text())
recipes={'covers':'Geniş fotoğraflı yatay kart rafı','lead-list':'Tek büyük tarif + üç küçük satır','grid':'İki sütun tarif ızgarası','numbered':'Süreye göre numaralı beşli','tabs':'Tümü / 30 dk / Kahvaltı rafı','stories':'Dikey editoryal kapaklar','timeline':'Süre etiketli tarif çizgisi','double-rail':'İki satır yatay raf','pair':'Şaşırtmalı ikili kartlar','mosaic':'Tam genişlik ilk kart + küçük grid','feed':'Tam genişlik ardışık kartlar','split':'Sağ/sol dönüşümlü görselli satırlar','accordion':'Açılır tarif seçkisi','gallery':'Büyük kapak + ikili kapak galerisi','index':'Fotoğraflı kısa tarif dizini'}
vid={'feature':'Büyük video + küçük grid','cinema':'Geniş yatay sinema rafı','rows':'Kapaklı video satırları','portraits':'Dikey video kapak rafı','duo':'İkili video grid + geniş son kart','playlist':'Büyük video + oynatma listesi'}
why={'1':'malzeme seçiminin cevabı fotoğraf ve tarif olarak görünür','2':'öğün bağlamı seçenekleri anlamlı biçimde daraltır','3':'az sayıdaki gerçek fikir arasında elle karşılaştırma sağlar','4':'kapak geri çekildikçe karar aracı daha çok yer bulur','5':'eldeki malzeme doğrudan somut tarif önerisine dönüşür','6':'soru ile yemek fotoğrafı ayrı hiyerarşide kalır','7':'kullanıcının ayırabildiği süre gerçek sonuçları belirler','8':'mutfak tercihi somut tariflere daralır','9':'iki seçeneğin fotoğrafı ve süresi karar yükünü azaltır','x1':'büyük kapak bekletmeden arama ve malzeme aracına ulaşılır','x2':'her tarif pişirilecek yemek için somut bir adaydır','x3':'iki malzeme ailesi karşılaştırmayı kolaylaştırır','x4':'kullanıcının ihtiyacına göre başlangıç yolu değişir','x5':'kapak açmak tarife ulaşan kısa bir keşif eylemidir','x6':'numaralı akış karar adımlarını okunur hale getirir'}
p=Path('v3-app/docs/36-ana-sayfa-setleri.md')
with p.open('a') as f:
 f.write('\n## On beş fikir ve başrol gerekçesi\n\n')
 for k,c in cfg.items():f.write(f"- **{k.upper()} · {c['name']}:** Bu alternatifin fikri {c['idea'][0].lower()+c['idea'][1:]}; başrol ne pişireceğine karar vermektir, çünkü {why[k]}.\n")
 f.write('\n## Bölüm karşılaştırması\n\n| Ekran | Tarifler | Şefler | Videolar | İlham |\n|---|---|---|---|---|\n')
 for k,c in cfg.items():f.write(f"| {k.upper()} · {c['name']} | {recipes[c['recipes']]} | {'Fotoğraflı mutfak zemini + şef şeridi' if c['separator']=='chefs' else 'Açık zemin + şef şeridi'} | {vid[c['video']]}{' · fotoğraflı ayırıcı' if c['separator']=='videos' else ' · açık zemin'} | {c['refs']} |\n")
 f.write('''\n## Tercih sıralaması\n\n**SET1: 2 → 1 → 7 → 3 → 8 → 9 → 6 → 5 → 4.** 2 günlük kullanıma hızlı giriyor ve büyük tarif + küçük liste dengeli. 1 en güvenli, onaylı görsel referans. 7 süre ihtiyacını net çözüyor. 3 karşılaştırması rahat;8 daha keşif odaklı;9 iki seçenekle karar yükünü azaltıyor. 6 daha editoryal,5 kapakta daha yoğun,4 uzun kapak nedeniyle karar aracını daha geç gösteriyor.\n\n**SET2: X1 → X4 → X3 → X6 → X2 → X5.** X1 uygulamanın işine en hızlı başlayan yapı. X4 farklı ihtiyaçları aynı başlangıçta topluyor; malzeme aracı bir sekme geride. X3 az seçenekle anlaşılır; X6 düzenli fakat defter ritmi daha uzun. X2 görsel keşif için güçlü ama karar aracı aşağıda; X5 etkileyici kapaklar sunuyor fakat yemek seçmek için ek dokunuş istiyor.\n\n**Önerim:** onaylı ailenin en dengeli adayı2, yapısal olarak daha uygulama odaklı adayX1. Bir sonraki seçim turunda1/2/X1/X4 dörtlüsünü karşılaştırmak anlamlı. Bu tur liste/detay uyarlaması veya yayın yapılmadı.\n''')
